80	
81	    @Column(name = "namesake_count")
82	    private Integer namesakeCount;
83	
84	    @Column(name = "membership_number")
85	    private String membershipNumber;
86	
87	    @Column(name = "bulk_signup_warning")
88	    private Boolean bulkSignupWarning;
89	
90	    @Column(name = "capacity_warning")
91	    private Boolean capacityWarning;
92	
93	    @Column(name = "household_size")
94	    private Integer householdSize;
95	
96	    @Column(name = "possible_duplicate")
97	    private Boolean possibleDuplicate;
98	
99	    @Column(name = "possible_duplicate_of")
100	    private Integer possibleDuplicateOf;
101	
102	    @Column(name = "membership_level_cap")
103	    private Integer membershipLevelCap;
104	
105	    @Column(name = "deleted", nullable = false)
106	    private Boolean deleted = false;
107	
108	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
109	    private Set<Pet> pets;
110	
111	    public String getTitle() {
112	        return this.title;
113	    }
114	
115	    public void setTitle(String title) {
116	        this.title = title;
117	    }
118	
119	    /**
120	     * The owner's salutation, composed from its {@link #getTitle() title} and
121	     * {@link #getLastName() last name}: {@code title + ' ' + lastName} when a title is
122	     * present, or just the last name when no title was supplied. Derived (not persisted);
123	     * recomputed each call. See {@link OwnerDerivations#salutation(String, String)}.
124	     *
125	     * @return the composed salutation
126	     */
127	    @Transient
128	    public String getSalutation() {
129	        return OwnerDerivations.salutation(this.title, this.getLastName());
130	    }
131	
132	    public String getAddress() {
133	        return this.address;
134	    }
135	
136	    public void setAddress(String address) {
137	        this.address = address;
138	    }
