163	
164	    /**
165	     * The owner's locality, i.e. the canonical region it belongs to (read from the
166	     * assigned {@link #customerCode} when present, otherwise derived from the owner's
167	     * own fields via {@link #regionForOwner()}). Derived (not persisted); recomputed
168	     * each call. See {@link OwnerDerivations#locality(String, String, String)} for the
169	     * full derivation.
170	     *
171	     * @return the canonical region string, or {@code "UNKNOWN"}
172	     */
173	    @Transient
174	    public String getLocality() {
175	        return OwnerDerivations.locality(this.customerCode, this.postcode, this.city);
176	    }
177	
178	    /**
179	     * The canonical region derived for this owner from its own fields. Recomputed each
180	     * call. See {@link OwnerDerivations#region(String, String)} for the derivation.
181	     *
182	     * @return the canonical region string, or {@code "UNKNOWN"}
183	     */
184	    public String regionForOwner() {
185	        return OwnerDerivations.region(this.postcode, this.city);
186	    }
187	
188	    /**
189	     * The owner's IANA timezone name, derived from its {@link #getLocality() locality}
190	     * (canonical region) via the fixed region-to-timezone table. Derived (not persisted);
191	     * recomputed each call and {@code null} when the locality is not a known region. See
192	     * {@link OwnerDerivations#timezone(String)} for the derivation.
193	     *
194	     * @return the IANA timezone name, or {@code null}
195	     */
196	    @Transient
197	    public String getTimezone() {
198	        return OwnerDerivations.timezone(this.getLocality());
199	    }
200	
201	    /**
202	     * Whether this owner's postcode is consistent with its {@link #getLocality()
203	     * locality}: an absent postcode is accepted, a present one must be exactly four
204	     * digits and, when the locality has a known postcode range, fall within it. See
205	     * {@link OwnerDerivations#postcodeMatchesRegion(String, String)}.
206	     *
207	     * @return {@code true} if the postcode is absent or valid for the owner's locality
208	     */
209	    public boolean postcodeValidForLocality() {
210	        return OwnerDerivations.postcodeMatchesRegion(this.postcode, this.getLocality());
211	    }
212	
213	    /**
214	     * The owner's membership points, a non-negative score derived from its factors.
215	     * Derived (not persisted); recomputed from the current fields each call, so it rises
216	     * once the owner's tenure since {@link #registrationDate} exceeds 365 days. See
217	     * {@link OwnerDerivations#membershipPoints(String, Integer, Integer, LocalDate, LocalDate)}
218	     * for how it is scored.
219	     *
220	     * @return the membership points, 0 or more
221	     */
222	    @Transient
223	    public Integer getMembershipPoints() {
224	        return OwnerDerivations.membershipPoints(this.email, this.namesakeCount, this.householdSize,
225	            this.registrationDate, LocalDate.now());
226	    }
227	
228	    /**
229	     * The owner's membership level, a number from 1 to 4, mapped from its
230	     * {@link #getMembershipPoints() membership points}. Derived (not persisted);
231	     * recomputed from the current fields each call, so it rises to level 4 once the
232	     * owner's tenure since {@link #registrationDate} exceeds 365 days. The level is then
233	     * held to this owner's household level ceiling ({@link #getMembershipLevelCap()}): when
234	     * a ceiling was assigned at creation the reported level is at most that ceiling, one
235	     * above the highest level then held by an existing household member. See
236	     * {@link OwnerDerivations#membershipLevel(int, Integer)} for the mapping.
237	     *
238	     * @return the membership level, from 1 to 4
239	     */
240	    @Transient
241	    public Integer getMembershipLevel() {
242	        return OwnerDerivations.membershipLevel(getMembershipPoints(), this.membershipLevelCap);
243	    }
244	
245	    /**
246	     * The owner's preferred contact channel, {@code "EMAIL"} or {@code "PHONE"}.
247	     * Derived (not persisted); recomputed from the current fields each call. See
248	     * {@link OwnerDerivations#contactPreference(String)}.
249	     *
250	     * @return {@code "EMAIL"} or {@code "PHONE"}
251	     */
252	    @Transient
253	    public String getContactPreference() {
