271	    public String getTelephoneDisplay() {
272	        return Telephones.toDisplay(this.telephone);
273	    }
274	
275	    public void setTelephone(String telephone) {
276	        this.telephone = telephone;
277	    }
278	
279	    public String getEmail() {
280	        return this.email;
281	    }
282	
283	    public void setEmail(String email) {
284	        this.email = email;
285	    }
286	
287	    public String getPostcode() {
288	        return this.postcode;
289	    }
290	
291	    public void setPostcode(String postcode) {
292	        this.postcode = postcode;
293	    }
