444	        this.deleted = deleted;
445	    }
446	
447	    /**
448	     * The derived key used for duplicate detection: the SHA-256 hex digest over this
449	     * owner's normalised telephone, lower-cased email and the {@link #soundex(String)
450	     * Soundex} of its last name. Two owners are duplicates exactly when their whole
451	     * identity keys are equal, so because the telephone is part of the key, members of
452	     * the same household with different telephones have different keys. Derived (not
453	     * persisted); recomputed each call. See
454	     * {@link OwnerDerivations#identityKey(String, String, String)} for the exact format.
455	     *
456	     * @return the owner's identity key
457	     */
458	    @Transient
459	    public String getIdentityKey() {
460	        return OwnerDerivations.identityKey(this.telephone, this.email, this.getLastName());
461	    }
462	
463	    /**
464	     * The American Soundex code of the given name. This is the last-name comparison used
465	     * by both the identity key and the soft-match duplicate check; see
466	     * {@link OwnerDerivations#soundex(String)} for the exact algorithm.
467	     *
468	     * @param value the name to encode (may be {@code null})
469	     * @return the four-character Soundex code, or the empty string
470	     */
471	    public static String soundex(String value) {
472	        return OwnerDerivations.soundex(value);
473	    }
474	
475	    /**
476	     * Compute the customer code to assign to this owner at creation, formatted
477	     * {@code <REGION>-<HASH8>} from the owner's (already normalised) fields. This is the
478	     * value stored in {@link #getCustomerCode()}; see
479	     * {@link OwnerDerivations#customerCode(String, String, String)} for the format.
480	     *
481	     * @return the customer code to assign
482	     */
483	    public String computeCustomerCode() {
484	        return OwnerDerivations.customerCode(regionForOwner(), this.telephone, this.getLastName());
485	    }
486	
487	    /**
488	     * Compute the membership number to assign to this owner at creation, formatted
489	     * {@code <customerCode>-M<YY>} from its already-assigned customer code and registration
490	     * date. This is the value stored in {@link #getMembershipNumber()}; see
491	     * {@link OwnerDerivations#membershipNumber(String, LocalDate)} for the exact format.
492	     *
493	     * @return the membership number to assign
494	     */
495	    public String computeMembershipNumber() {
496	        return OwnerDerivations.membershipNumber(this.customerCode, this.registrationDate);
497	    }
498	
499	    /**
500	     * Compute the stable household identifier for this owner, derived deterministically
501	     * from its last name and postcode so every owner sharing a last name and postcode
502	     * resolves to the same value. This is the value stored in {@link #getHouseholdId()};
503	     * see {@link OwnerDerivations#householdId(String, String)} for the exact derivation.
504	     *
505	     * @return the household identifier
506	     */
507	    public String computeHouseholdId() {
508	        return OwnerDerivations.householdId(normalize(this.getLastName()), this.postcode);
509	    }
510	
511	    /**
512	     * Whether this owner belongs to the same household as {@code other}: that is, they
513	     * share the same last name and postcode. The last name is compared
514	     * case-insensitively with runs of whitespace collapsed to a single space (and
515	     * surrounding whitespace trimmed); the postcode is compared for exact equality (two
516	     * absent postcodes count as equal). Owners in the same household resolve to the same
517	     * {@link #computeHouseholdId() household identifier}.
518	     *
519	     * @param other the owner to compare against
520	     * @return {@code true} if both owners share a household
521	     */
522	    public boolean sameHouseholdAs(Owner other) {
523	        return normalize(this.getLastName()).equals(normalize(other.getLastName()))
524	            && Objects.equals(this.postcode, other.postcode);
525	    }
526	
527	    /**
528	     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
529	     * trim, collapse internal runs of whitespace to a single space and lower-case.
530	     */
531	    private static String normalize(String value) {
532	        return OwnerDerivations.collapseWhitespace(value).toLowerCase();
533	    }
534	
535	    /**
536	     * Reduce an address to its canonical stored form. This is the value stored,
537	     * returned and used for every household comparison; see
538	     * {@link OwnerDerivations#normalizeAddress(String)} for the exact normalisation.
539	     *
540	     * @param value the raw address (may be {@code null})
541	     * @return the normalised address, or the empty string if {@code value} is
542	     *         {@code null} or blank
543	     */
544	    public static String normalizeAddress(String value) {
545	        return OwnerDerivations.normalizeAddress(value);
546	    }
547	
548	    protected Set<Pet> getPetsInternal() {
549	        if (this.pets == null) {
550	            this.pets = new HashSet<>();
551	        }
552	        return this.pets;
553	    }
554	
555	    protected void setPetsInternal(Set<Pet> pets) {
556	        this.pets = pets;
557	    }
558	
559	    public List<Pet> getPets() {
560	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
561	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
562	        return Collections.unmodifiableList(sortedPets);
563	    }
564	
565	    public void setPets(List<Pet> pets) {
566	        this.pets = new HashSet<>(pets);
567	    }
568	
569	    public void addPet(Pet pet) {
570	        getPetsInternal().add(pet);
571	        pet.setOwner(this);
572	    }
573	
574	    /**
575	     * Return the Pet with the given name, or null if none found for this Owner.
576	     *
577	     * @param name to test
578	     * @return true if pet name is already in use
579	     */
580	    public Pet getPet(String name) {
581	        return getPet(name, false);
582	    }
583	
584	    /**
585	     * Return the Pet with the given name, or null if none found for this Owner.
586	     *
587	     * @param name to test
588	     * @return true if pet name is already in use
589	     */
590	    public Pet getPet(String name, boolean ignoreNew) {
591	        name = name.toLowerCase();
592	        for (Pet pet : getPetsInternal()) {
593	            if (!ignoreNew || !pet.isNew()) {
594	                String compName = pet.getName();
595	                compName = compName.toLowerCase();
596	                if (compName.equals(name)) {
597	                    return pet;
598	                }
599	            }
600	        }
601	        return null;
602	    }
603	
604	    public Pet getPet(Integer petId) {
605	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
606	    }
607	
608	    @Override
609	    public String toString() {
610	        return new ToStringCreator(this)
611	
612	            .append("id", this.getId())
613	            .append("new", this.isNew())
614	            .append("lastName", this.getLastName())
615	            .append("firstName", this.getFirstName())
616	            .append("address", this.address)
617	            .append("city", this.city)
618	            .append("telephone", this.telephone)
619	            .toString();
620	    }
621	}
